const run_id = new Date().toISOString() + '-' + Math.random().toString(36).substring(2, 9);

// Add the run_id to all items.
for (const item of items) {
  item.json.run_id = run_id;
}
return items;

const rows = items;
const symbols = [];
const lines = [];
for (const r of rows) {
  const sym = String(r.json.symbol || '').toUpperCase().trim();
  if (!sym) continue;
  symbols.push(sym);
  const parts = [sym];
  lines.push('- ' + parts.join(' '));
}
const portfolioContext = ['My portfolio:', ...lines.slice(0, 200)].join('\n');
return [{ json: { symbols, portfolioContext } }];

function stripHtml(html) {
  if (!html) return '';
  // Remove scripts/styles
  html = html.replace(/<script[\s\S]*?<\/script>/gi, '')
             .replace(/<style[\s\S]*?<\/style>/gi, '');
  // Replace <br> and <p> with line breaks to preserve some structure
  html = html.replace(/<(br|\/p|\/div)\s*\/?>/gi, '\n');
  // Strip all remaining tags
  let text = html.replace(/<[^>]+>/g, ' ');
  // Unescape common HTML entities (lightweight)
  text = text.replace(/&nbsp;/gi, ' ')
             .replace(/&amp;/gi, '&')
             .replace(/&lt;/gi, '<')
             .replace(/&gt;/gi, '>')
             .replace(/&#39;/gi, "'")
             .replace(/&quot;/gi, '"');
  // Collapse whitespace
  return text.replace(/\r?\n|\r/g, ' ').replace(/\s+/g, ' ').trim();
}

function extractLinks(s) {
  if (!s) return [];
  const links = new Set();
  const re = /\bhttps?:\/\/[^\s)>"']+/gi;
  let m;
  while ((m = re.exec(s)) !== null) {
    // basic tracker trim (utm, mc, etc.) — optional
    let url = m[0];
    try {
      const u = new URL(url);
      ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','mc_cid','mc_eid'].forEach(p => u.searchParams.delete(p));
      url = u.toString();
    } catch {}
    links.add(url);
  }
  return Array.from(links);
}

return items.map(it => {
  const headers = it.json.headers;
  const subject = String(it.json.subject || '').trim();
  const from    = String(headers.from || '').trim();
  const date    = String(it.json.date || '').trim();
  const to      = String(headers.to || '').trim();
  const messageId = it.json.messageId

  // Prefer plain text → textAsHtml → html
  let body = '';
  if (it.json.text && String(it.json.text).trim().length > 0) {
    body = String(it.json.text);
  } else if (it.json.textAsHtml && String(it.json.textAsHtml).trim().length > 0) {
    body = stripHtml(String(it.json.textAsHtml));
  } else if (it.json.html && String(it.json.html).trim().length > 0) {
    body = stripHtml(String(it.json.html));
  }

  // Final normalization + clamp
  body = String(body).replace(/\r?\n|\r/g, ' ').replace(/\s+/g, ' ').trim();
  const MAX = 12000; // keep token cost in check
  if (body.length > MAX) body = body.slice(0, MAX);

  const links = extractLinks(`${it.json.text || ''}\n${it.json.textAsHtml || ''}\n${it.json.html || ''}`);

  return {
    json: {
      subject, from, date, to,
      body,
      bodyShort: body.slice(0, 500),
      messageId: it.json.id
    }
  };
});

