const items = $input.all();

for (const item of items) {
  try {
    // Safely access the text using optional chaining (?.) to prevent crashes
    const aiOutputObject = item.json.output?.[0]?.content?.[0]?.text;

    if (!aiOutputObject || typeof aiOutputObject !== 'object') {
      throw new Error("AI output was not a valid object.");
    }

    // Place the clean data at the top level for easy access later
    item.json.priority = aiOutputObject.priority || 'normal';
    item.json.confidence = aiOutputObject.confidence || 1;
    item.json.summary = aiOutputObject.summary || 'No summary provided.';

    if (item.json.priority === 'high' && item.json.confidence < 0.65) {
      item.json.priority = 'normal';
    }
  } catch (e) {
    // If anything fails, we log the error and default to 'normal' to be safe
    console.log(`Failed to parse AI output. Error: ${e.message}`);
    item.json.priority = "junk";
    item.json.summary = "Error: AI output was malformed or missing.";
  }
}

return items;

// Build a Telegram-safe HTML message in json.telegramMessage

function escHTML(text) {
  if (typeof text !== "string" || text.length === 0) return "";
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

return items.map(it => {
  const subj = (it.json.subject || '(no subject)').replace(/^Subject:\s*/i,'');
  const from = (it.json.from || '(unknown sender)').replace(/^From:\s*/i,'');
  const date = new Date(it.json.date).toLocaleString("en-UK", {
    dateStyle: "full",
    timeStyle: "short",
  });
  let summary = it.json.summary || '—';

  summary = escHTML(summary).replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

  const errorMsg = 'This email was marked as JUNK';

  const msg =
`<b>📊 Portfolio Impact Alert</b>
<i>${escHTML(errorMsg)}</i>

Subject: ${escHTML(subj)}
From: ${escHTML(from)}
Date: ${escHTML(date)}

${escHTML(summary)}`;

  // Telegram limit ~4096 chars
  const MAX = 3900;
  let safe = msg.length > MAX ? msg.slice(0, MAX) + '…' : msg;

  // Add Support Footer
  safe += `\n\n<a href="https://www.buymeacoffee.com/fabcarvalho">Support this project ☕</a>`;

  return {
    json: {
      telegramMessage: safe,
      messageId: it.json.messageId,
      subject: it.json.subject,
      priority: it.json.priority,
      summary
    }
  };
});

