// This node validates and sanitizes the output from the final analysis AI.

const VALID_ACTIONS = new Set([
  "REVIEW",
  "WATCH",
  "HOLD",
  "TRIM",
  "ADD",
  "REDUCE",
  "NONE",
]);

return items.map((it) => {
  let aiOutputObject = {};
  try {
    // Access the object directly, NO JSON.parse()
    const output = it.json.output?.[0]?.content?.[0]?.text;
    if (output && typeof output === "object") {
      aiOutputObject = output;
    }
  } catch (e) {
    console.error("Failed to access final analysis output:", e.message);
  }

  // --- Validation and Defaulting ---
  const summary = aiOutputObject.summary || "AI summary was not provided.";
  const notes = aiOutputObject.notes || "";
  const rawActions = Array.isArray(aiOutputObject.actions)
    ? aiOutputObject.actions
    : [];

  // --- Deep Validation of the 'actions' Array ---
  const sanitizedActions = rawActions.map((action) => {
    let suggestedAction = (action.suggestedAction || "NONE").toUpperCase();
    if (!VALID_ACTIONS.has(suggestedAction)) {
      suggestedAction = "NONE";
    }
    const clamp = (num, min, max) => Math.min(Math.max(num, min), max);
    const confidence = clamp(Number(action.confidence || 0), 0, 100);
    const riskScore = clamp(Number(action.riskScore || 0), 0, 100);

    return {
      symbol: action.symbol || "UNKNOWN",
      impact: action.impact || "No impact analysis provided.",
      suggestedAction: suggestedAction,
      timeHorizon: action.timeHorizon || "N/A",
      confidence: confidence,
      riskScore: riskScore,
    };
  });

  const actionable = sanitizedActions.some((a) => a.suggestedAction !== "NONE");

  return {
    json: {
      subject: it.json.subject,
      from: it.json.from,
      date: it.json.date,
      messageId: it.json.messageId,
      priority: it.json.priority, // Pass through from the triage step
      ai: {
        summary: summary,
        actions: sanitizedActions,
        notes: notes,
        model: it.json.model
      },
      hasAction: actionable,
    },
  };
});

// Paste this entire code block into your "Prepare Message" node

function escHTML(text) {
  if (typeof text !== "string" || text.length === 0) return "";
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function normalizeTo100(value) {
  if (value == null || isNaN(value)) return 0;
  let num = Number(value);

  if (num > 1 && num <= 10) {
    // If the scale seems to be 0-10 (e.g., a risk score of 6)
    num *= 10;
  } else if (num <= 1) {
    // If the scale seems to be 0-1 (e.g., 0.75)
    num *= 100;
  }
  // Otherwise, we assume it's already on a 0-100 scale.
  //  // Finally, clamp the value to be safely between 0 and 100
  return Math.min(Math.max(Math.round(num), 0), 100);
}

function heatEmoji(confPct, riskPct) {
  if (riskPct > 75 && confPct > 60) return "🔴";
  if (riskPct > 50 && confPct > 50) return "🟠";
  if (riskPct > 30 && confPct > 40) return "🟡";
  return "🟢";
}

return items.map((it) => {
  const hasAction = it.json.hasAction;
  let msg;

  // Sanitize all dynamic content first
  const priority = `(${(it.json.priority || "NORMAL").toUpperCase()})`;
  let summary = it.json.ai?.summary || "—";
  const notes = it.json.ai?.notes || "–";
  const subj = it.json.subject || "(no subject)";
  const from = it.json.from || "(unknown sender)";
  const date = new Date(it.json.date).toLocaleString("en-US", {
    dateStyle: "full",
    timeStyle: "short",
  });

  // Convert Markdown Bold in Summary to HTML Bold ---
  summary = escHTML(summary).replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

  if (hasAction) {
    const actions = Array.isArray(it.json.ai?.actions)
      ? it.json.ai.actions
      : [];
    let actionsText = actions
      .map((a) => {
        const conf = normalizeTo100(a.confidence);
        const risk = normalizeTo100(a.riskScore);
        // Escape each piece of content individually
        return `• ${heatEmoji(conf, risk)} <b>${escHTML(a.symbol || "—")}</b> → ${escHTML(a.suggestedAction || "INFO")} (${escHTML(a.timeHorizon || "—")}, conf ${conf}%, risk ${risk}%)\n${escHTML(a.impact || "No impact provided.")}`;
      })
      .join("\n\n");

    // Now, build the message with HTML tags
    msg = `<b>📊 Portfolio Impact Alert ${escHTML(priority)}</b>\n${summary}\n\n<b>Actions</b>\n${actionsText}\n\n<b>Notes: </b>${escHTML(notes)}`;
  } else {
    msg = `<b>📄 FYI ${escHTML(priority)}: ${escHTML(subj)}</b>\n${summary}`;
  }

  const footer = `\n\n---\nFrom: ${escHTML(from)}\nDate: ${escHTML(date)}\n\n<a href="https://www.buymeacoffee.com/fabcarvalho">Support this project ☕</a>`;
  const finalMsg = msg + footer;

  const MAX_LENGTH = 4096;
  const safeMsg = finalMsg.length > MAX_LENGTH
      ? finalMsg.substring(0, MAX_LENGTH - 3) + "..."
      : finalMsg;

  return { json: { ...it.json, telegramMessage: safeMsg } };
});

const finalLogs = [];

for (const item of items) {
  const logEntry = {
    run_id: $('Generate Run ID').first().json.run_id,
    message_id: item.json.messageId,
    email_subject: item.json.subject,
    triage_priority: item.json.priority,
    actionable_item_count: 0,
    total_item_count: 0,
  };

  // Check if there was an AI analysis to count actions from
  if (item.json.ai) {
  logEntry.analysis_model = item.json.ai.model || "";
  if (Array.isArray(item.json.ai.actions)) {
    logEntry.total_item_count = item.json.ai.actions.length;
    logEntry.actionable_item_count = item.json.ai.actions.filter(
      (a) => a.suggestedAction !== "NONE"
    ).length;
  }
}


  // If there was an error message from a previous step, log it
  if (item.json.priority === 'junk' && item.json.summary) {
    logEntry.has_error = true;
    logEntry.error_message = item.json.summary;
  }

  finalLogs.push({ json: logEntry });
}

return finalLogs;
